(* MemoryAllocation *)
memory_allocation_term = (memory_storage_1_term, ".", "allocation" | memory_storage_2_term, ".", "allocation" | memory_region_term, ".", "allocation" | "(", memory_allocation_term, ")") ;
(* MemoryBool *)
